import java.util.HashSet;
import java.util.Set;

public class Main {
    static int firstDuplicate(int[] a) {
        Set<Integer> seen = new HashSet<>();
        for (int n : a) {
            if (!seen.add(n)) {
                return n;
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        System.out.println(firstDuplicate(new int[] {2, 5, 3, 5, 2}));
    }
}
